#pragma once

#include <QStringList>

// Small bridges to AppKit for things Qt does not expose.
namespace MacPasteboard {

// True when the general pasteboard carries the nspasteboard.org markers password
// managers set (org.nspasteboard.ConcealedType / TransientType / AutoGeneratedType).
// Such items must never leave the Mac or be kept in history.
bool isConcealed();

// System "Reduce motion" accessibility preference.
bool reduceMotion();

// Opens Finder with the given files selected.
void revealInFinder(const QStringList& paths);

} // namespace MacPasteboard
